glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1.0);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D maskTexture;
#endif

uniform PROPERTIES {
  vec4 pieceUvRect;
  vec4 maskUvRect;
};

void main () {
  vec2 uvSize = max(pieceUvRect.zw, vec2(0.0001, 0.0001));
  vec2 localFromRect = (v_uv0 - pieceUvRect.xy) / uvSize;
  float insidePieceRect = step(0.0, localFromRect.x) * step(localFromRect.x, 1.0) * step(0.0, localFromRect.y) * step(localFromRect.y, 1.0);
  vec2 localUv = mix(clamp(v_uv0, 0.0, 1.0), clamp(localFromRect, 0.0, 1.0), insidePieceRect);
  vec2 sampleUv = mix(pieceUvRect.xy + localUv * uvSize, v_uv0, insidePieceRect);
  vec2 sourceUv = clamp(sampleUv, 0.0, 1.0);
  vec4 texel = texture2D(texture, sourceUv);
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    texel.a *= texture2D(texture, sourceUv + vec2(0.0, 0.5)).r;
  #endif
  texel *= v_color;
  if (texel.a <= 0.001) {
    discard;
  }

  vec2 maskUv = maskUvRect.xy + clamp(localUv, 0.0, 1.0) * maskUvRect.zw;
  vec4 maskTexel = texture2D(maskTexture, clamp(maskUv, 0.0, 1.0));
  float shapeAlpha = smoothstep(0.08, 0.55, max(maskTexel.a, maskTexel.r));
  if (shapeAlpha <= 0.004) {
    discard;
  }

  gl_FragColor = vec4(texel.rgb, texel.a * shapeAlpha);
}

